import styles from './tech.module.css';
import Image from 'next/image';
import content from '../../data/content.json';

const TechPage = () => {
    return (
        <div className={styles.container}>
            <section className={styles.intro}>
                <h1 className="section-title">{content.tech.introTitle}</h1>
                <p className={styles.introText}>
                    {content.tech.introText}
                </p>
            </section>

            <section className={styles.equipmentGrid}>
                {content.tech.equipment.map((item: any) => (
                    <div key={item.name} className={`${styles.techCard} glass-card`}>
                        <div className={styles.cardImage}>
                            <Image src={item.image} alt={item.name} width={400} height={300} objectFit="cover" />
                        </div>
                        <div className={styles.cardContent}>
                            <div className={styles.cardHeader}>
                                <h2 className={styles.itemName}>{item.name}</h2>
                                <span className={styles.itemQty}>{item.qty}</span>
                            </div>
                            <p className={styles.itemDesc}>{item.desc}</p>
                            <div className={styles.usageBox}>
                                <h4 className={styles.usageTitle}>ДЛЯ ЧЕГО НУЖЕН:</h4>
                                <p className={styles.usageText}>{item.usage}</p>
                            </div>
                        </div>
                    </div>
                ))}
            </section>
        </div>
    );
};

export default TechPage;
